        "items": [
          {
            "type": 1,
            "content": {
              "json": "## Previous-generation VM capacity readiness\r\n\r\nStarting in July 2026, Azure applies capacity limitations to specific\r\nprevious-generation VM series. Existing running VMs continue to operate; the risk is\r\nfuture quota growth, new deployments, and scale-out on hardware with limited capacity.\r\n\r\nThis workbook uses Microsoft's explicit affected-series list. It does **not** assume\r\nthat every VM whose name contains `v1` through `v4` is affected.",
              "style": "warning"
            },
            "name": "ovHeader"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "resources\n| where type =~ 'microsoft.compute/virtualmachines'\n    or type =~ 'microsoft.compute/virtualmachinescalesets'\n| extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n| extend _regions = dynamic([{Regions}])\n| where array_length(_regions) == 0 or set_has_element(_regions, '*') or set_has_element(_regions, location)\n| extend\n    ResourceKind = iff(type =~ 'microsoft.compute/virtualmachines', 'VM', 'VMSS'),\n    TargetId = tolower(id),\n    VmSize = iff(type =~ 'microsoft.compute/virtualmachines', tostring(properties.hardwareProfile.vmSize), tostring(sku.name)),\n    CurrentCapacity = iff(type =~ 'microsoft.compute/virtualmachines', 1, coalesce(toint(sku.capacity), 0)),\n    OperatingSystem = iff(type =~ 'microsoft.compute/virtualmachines', tostring(properties.storageProfile.osDisk.osType), ''),\n    Priority = iff(type =~ 'microsoft.compute/virtualmachines', tostring(properties.priority), ''),\n    AvailabilitySet = iff(type =~ 'microsoft.compute/virtualmachines', extract('/availabilitySets/([^/]+)$', 1, tostring(properties.availabilitySet.id)), ''),\n    EphemeralOS = iff(type =~ 'microsoft.compute/virtualmachines', tostring(properties.storageProfile.osDisk.diffDiskSettings.option) =~ 'Local', false),\n    OrchestrationMode = tostring(properties.orchestrationMode),\n    UpgradeMode = tostring(properties.upgradePolicy.mode),\n    Zones = strcat_array(zones, ', ')\n| extend _sizeKey = toupper(VmSize)\n| extend Series = case(\n    _sizeKey matches regex '^STANDARD_F[0-9]+S_V2$', 'Fsv2',\n    _sizeKey matches regex '^STANDARD_FS[0-9]+_V2$', 'Fsv2',\n    _sizeKey matches regex '^STANDARD_FS[0-9]+$', 'Fs',\n    _sizeKey matches regex '^STANDARD_F[0-9]+[A-Z]*S$', 'Fs',\n    _sizeKey matches regex '^STANDARD_F[0-9]+$', 'F',\n    _sizeKey matches regex '^STANDARD_D[0-9]+I?DS_V4$', 'Ddsv4',\n    _sizeKey matches regex '^STANDARD_D[0-9]+I?D_V4$', 'Ddv4',\n    _sizeKey matches regex '^STANDARD_D[0-9]+AS_V4$', 'Dasv4',\n    _sizeKey matches regex '^STANDARD_D[0-9]+A_V4$', 'Dav4',\n    _sizeKey matches regex '^STANDARD_D[0-9]+I?S_V4$', 'Dsv4',\n    _sizeKey matches regex '^STANDARD_D[0-9]+I?_V4$', 'Dv4',\n    _sizeKey matches regex '^STANDARD_D[0-9]+I?S_V3$', 'Dsv3',\n    _sizeKey matches regex '^STANDARD_D[0-9]+I?_V3$', 'Dv3',\n    _sizeKey matches regex '^STANDARD_DS[0-9]+_V2$', 'Dsv2',\n    _sizeKey matches regex '^STANDARD_D[0-9]+I?S_V2$', 'Dsv2',\n    _sizeKey matches regex '^STANDARD_D[0-9]+I?_V2$', 'Dv2',\n    _sizeKey matches regex '^STANDARD_DS[0-9]+$', 'Ds',\n    _sizeKey matches regex '^STANDARD_D[0-9]+S$', 'Ds',\n    _sizeKey matches regex '^STANDARD_D[0-9]+$', 'D',\n    _sizeKey matches regex '^STANDARD_B[0-9]+[A-Z]*S$', 'Bs',\n    _sizeKey matches regex '^STANDARD_B[0-9]+[A-Z]*$', 'B',\n    _sizeKey matches regex '^STANDARD_A[0-9]+M_V2$', 'Amv2',\n    _sizeKey matches regex '^STANDARD_A[0-9]+_V2$', 'Av2',\n    _sizeKey matches regex '^STANDARD_E[0-9]+I?DS_V4$', 'Edsv4',\n    _sizeKey matches regex '^STANDARD_E[0-9]+I?D_V4$', 'Edv4',\n    _sizeKey matches regex '^STANDARD_E[0-9]+AS_V4$', 'Easv4',\n    _sizeKey matches regex '^STANDARD_E[0-9]+A_V4$', 'Eav4',\n    _sizeKey matches regex '^STANDARD_E[0-9]+I?S_V4$', 'Esv4',\n    _sizeKey matches regex '^STANDARD_E[0-9]+I?_V4$', 'Ev4',\n    _sizeKey matches regex '^STANDARD_E[0-9]+I?S_V3$', 'Esv3',\n    _sizeKey matches regex '^STANDARD_E[0-9]+I?_V3$', 'Ev3',\n    _sizeKey matches regex '^STANDARD_GS[0-9]+$', 'Gs',\n    _sizeKey matches regex '^STANDARD_G[0-9]+S$', 'Gs',\n    _sizeKey matches regex '^STANDARD_G[0-9]+$', 'G',\n    _sizeKey matches regex '^STANDARD_L[0-9]+S_V2$', 'Lsv2',\n    _sizeKey matches regex '^STANDARD_L[0-9]+S$', 'Ls',\n    '')\n| extend Category = case(\n    Series in ('F','Fs','Fsv2'), 'Compute optimized',\n    Series in ('D','Ds','Dv2','Dsv2','Dv3','Dsv3','Dv4','Dsv4','Ddv4','Ddsv4','Dav4','Dasv4','B','Bs','Av2','Amv2'), 'General purpose',\n    Series in ('Ev3','Esv3','Ev4','Esv4','Edv4','Edsv4','Eav4','Easv4','G','Gs'), 'Memory optimized',\n    Series in ('Ls','Lsv2'), 'Storage optimized',\n    '')\n| extend RetirementDate = case(\n    Series in ('D','Ds','Dv2','Dsv2','Ls'), datetime(2028-05-01),\n    Series in ('Av2','Amv2','B','Bs','F','Fs','Fsv2','G','Gs','Lsv2'), datetime(2028-11-15),\n    todatetime(''))\n| extend LifecycleStatus = case(\n    isnotnull(RetirementDate), 'Capacity restricted + retirement scheduled',\n    isnotempty(Series), 'Capacity restricted; product active',\n    'Current generation')\n| extend RecommendedTarget = case(\n    Series in ('D','Ds','Dv2','Dsv2','Dv3','Dsv3','Dv4','Dsv4','Ddv4','Ddsv4','Dav4','Dasv4'), 'Dv5/Dsv5, Dv6/Dsv6, or Dv7/Dsv7',\n    Series in ('Ev3','Esv3','Ev4','Esv4','Edv4','Edsv4','Eav4','Easv4'), 'Ev5/Esv5, Esv6, or Esv7',\n    Series in ('Av2','Amv2'), 'Bsv2/Basv2 or D/E v5-v6',\n    Series in ('B','Bs'), 'Bsv2/Basv2 or Dlsv5-v6',\n    Series in ('F','Fs','Fsv2'), 'Dlsv5-v6, Dsv5, or Falsv6',\n    Series in ('G','Gs'), 'Lsv3/Lasv3 or Lsv4/Lasv4',\n    Series in ('Ls','Lsv2'), 'Lsv3/Lasv3 or Lsv4/Lasv4',\n    '')\n| project-away _sizeKey\n| where isnotempty(Series)\n| join kind=leftouter (\n    resources\n    | where type =~ 'microsoft.insights/autoscalesettings'\n    | mv-expand Profile = properties.profiles\n    | extend\n        TargetId = tolower(tostring(properties.targetResourceUri)),\n        ProfileMin = toint(Profile.capacity.minimum),\n        ProfileMax = toint(Profile.capacity.maximum)\n    | summarize AutoscaleMin = min(ProfileMin), AutoscaleMax = max(ProfileMax), AutoscaleProfiles = count() by TargetId\n  ) on TargetId\n| extend\n    AutoscaleMin = iff(ResourceKind == 'VM', 1, coalesce(AutoscaleMin, CurrentCapacity)),\n    AutoscaleMax = iff(ResourceKind == 'VM', 1, coalesce(AutoscaleMax, CurrentCapacity))\n| extend GrowthGap = iff(AutoscaleMax > CurrentCapacity, AutoscaleMax - CurrentCapacity, 0)\n| join kind=leftouter (\n    resourcecontainers\n    | where type =~ 'microsoft.resources/subscriptions'\n    | project subscriptionId, Subscription = name\n  ) on subscriptionId\n| extend\n    InstanceCount = CurrentCapacity,\n    Risk = case(ResourceKind == 'VMSS' and GrowthGap > 0, 'Critical', isnotnull(RetirementDate), 'High', 'Medium'),\n    RiskReason = case(\n        ResourceKind == 'VMSS' and GrowthGap > 0, 'Autoscale or planned growth uses a capacity-restricted series',\n        isnotnull(RetirementDate), 'Retirement scheduled and capacity growth restricted',\n        'Capacity growth restricted'),\n    MigrationConsiderations = strcat_array(array_concat(\n        iff(ResourceKind == 'VM' and isnotempty(AvailabilitySet), pack_array('Coordinate availability-set migration'), dynamic([])),\n        iff(ResourceKind == 'VM' and isnotempty(Zones), pack_array('Validate target size in current zone'), dynamic([])),\n        iff(ResourceKind == 'VM' and EphemeralOS, pack_array('Ephemeral OS disk - plan redeployment'), dynamic([])),\n        iff(ResourceKind == 'VM' and Priority =~ 'Spot', pack_array('Spot workload - validate replacement capacity'), dynamic([])),\n        iff(ResourceKind == 'VMSS' and GrowthGap > 0, pack_array(strcat('Autoscale growth gap: ', tostring(GrowthGap))), dynamic([])),\n        iff(ResourceKind == 'VMSS' and isnotempty(Zones), pack_array('Validate target size in every configured zone'), dynamic([])),\n        iff(ResourceKind == 'VMSS' and OrchestrationMode =~ 'Uniform', pack_array('Coordinate model and instance upgrade'), dynamic([]))\n      ), ' | '),\n    RiskRank = case(ResourceKind == 'VMSS' and GrowthGap > 0, 0, isnotnull(RetirementDate), 1, 2),\n    Resource = name,\n    Location = location,\n    ResourceId = id,\n    ResourceGroup = resourceGroup,\n    SubscriptionId = subscriptionId\n| summarize\n    AffectedInstances = sum(InstanceCount),\n    StandaloneVMs = countif(ResourceKind == 'VM'),\n    ScaleSets = countif(ResourceKind == 'VMSS'),\n    GrowthAtRisk = sum(GrowthGap),\n    RetirementScheduled = sumif(InstanceCount, isnotnull(RetirementDate)),\n    AffectedSubscriptions = dcount(SubscriptionId),\n    Regions = dcount(Location)\n| extend MetricRows = pack_array(\n    strcat('1|Affected VM instances|', tostring(AffectedInstances)),\n    strcat('2|Standalone VMs|', tostring(StandaloneVMs)),\n    strcat('3|VM scale sets|', tostring(ScaleSets)),\n    strcat('4|Autoscale growth at risk|', tostring(GrowthAtRisk)),\n    strcat('5|Retirement-scheduled instances|', tostring(RetirementScheduled)),\n    strcat('6|Affected subscriptions|', tostring(AffectedSubscriptions)),\n    strcat('7|Affected regions|', tostring(Regions))\n  )\n| mv-expand MetricRow = MetricRows to typeof(string)\n| extend MetricParts = split(MetricRow, '|')\n| project\n    Rank = toint(MetricParts[0]),\n    Metric = tostring(MetricParts[1]),\n    Value = tolong(MetricParts[2])\n| order by Rank asc",
              "size": 3,
              "title": "Capacity exposure summary",
